from math import gcd
from functools import reduce

def read_input():
    return map(int, sys.stdin.readline().split())

def find_sequence(n, k):
    if n < k or n % k != 0:
        return -1

    base = n // k
    seq = [base] * k

    # Calculate GCD of the initial sequence
    current_gcd = reduce(gcd, seq)

    # Adjust the sequence to maximize the GCD
    for i in range(k):
        while current_gcd > 1 and seq[i] % current_gcd != 0:
            seq[i] -= 1
            current_gcd = gcd(current_gcd, seq[i])

    # Check if the final sequence meets the requirements
    if sum(seq) == n and len(set(map(lambda x: x // gcd(x, seq[0]), seq))) == 1:
        return ' '.join(map(str, seq))
    else:
        return -1

if __name__ == "__main__":
    n, k = read_input()
    result = find_sequence(n, k)
    print(result)
